\begin{proposition}[The inclusion of a regular level set is a smooth immersion]
\label{prop:regular-level-set-inclusion-smooth}

\uses{prop:regular-level-set-hypersurface-codim-one}




In the situation of Proposition \ref{prop:regular-level-set-hypersurface-codim-one}, the inclusion $\iota_c : f^{-1}(c) \hookrightarrow M$ is smooth, and its differential is injective at every point. Since $\iota_c$ is a topological embedding, $f^{-1}(c)$ is an embedded smooth hypersurface in $M$.
\end{proposition}

\begin{proof}

\uses{prop:regular-level-set-hypersurface-codim-one,def:level-slice-chart}
Read in the slice chart at $x_0$ and the chart $\kappa$ of $M$, the inclusion is $z \mapsto G^{-1}(\kappa(x_0) + \iota(z))$, a composite of an affine map with a smooth map; hence it is smooth. Its differential at the centre is $d(G^{-1})_{\kappa(x_0)} \circ \iota$. Here $\iota$ is injective, being a linear isomorphism onto $\ker df_{x_0}$; and $d(G^{-1})_{\kappa(x_0)}$ is injective because $dG_{\kappa(x_0)} \circ d(G^{-1})_{\kappa(x_0)} = \operatorname{id}$, which follows by differentiating $G \circ G^{-1} = \operatorname{id}$ near $\kappa(x_0)$. A composite of injective maps is injective. Finally $\iota_c$ is a topological embedding because it is the inclusion of a subspace.
\end{proof}

